#define ZD1_REG_SELECT             0xC2  /* F W: Ours: b0 = a [`player`] receiver to bring to the front, as a person chose it on the speaker (the ON/OFF key, the host link's Select): zd1-linkd tells the others to pause their senders and that one to resume. */
