/* 'F' (2 data bytes) or 'V' (16-bit LE length + data) for every register: ours, else the stock firmware's table */
static inline char zd1_reg_kind(uint8_t reg){
    static const uint8_t v[32] = {0x01,0x00,0x00,0x00,0xE0,0xF0,0x08,0xF7,0xA1,0xD8,0x20,0xF3,0x7E,0x13,0xA0,0x0B,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x68,0xA9,0x47,0x30,0x10,0x00,0x00,0x00};
    return (v[reg >> 3] >> (reg & 7)) & 1 ? 'V' : 'F';
}

/* ---- DRC codes (MCU -> module on 0x48, b0) ---- */
#define ZD1_DRC_JBC_START      0x9D  /* ack -: JBConnect: start the setup network (after Networking/JBCONNECT/JBCSSID). */
#define ZD1_DRC_WIRELESS_APPLY 0x9E  /* ack -: Re-apply the wireless settings (sent when NetIF/mode was set to wireless). */
#define ZD1_DRC_JBC_STOP       0x9F  /* ack -: JBConnect: stop the setup network. */
#define ZD1_DRC_NEXT           0xB0  /* ack -: Next track (key/IR on the Wi-Fi source). */
#define ZD1_DRC_PREV           0xB1  /* ack -: Previous track. */
#define ZD1_DRC_PLAY_PAUSE     0xB3  /* ack -: Play/pause toggle (IR). */
#define ZD1_DRC_PAUSE          0xDE  /* ack 1: Pause: leaving the Wi-Fi source (other source, standby, iPod docked). */
#define ZD1_DRC_PLAY           0xDF  /* ack 0: Play/resume: entering the Wi-Fi source, and the startup resume. */
#define ZD1_DRC_RELEASE        0xE1  /* ack 4: Release the audio path: leaving Wi-Fi for a local source or standby. */
#define ZD1_DRC_ENABLE         0xE2  /* ack 5: (Re)enable the audio path: entering the Wi-Fi source, and at boot. */
/* the value the module acknowledges a DRC code with on 0xE3 (b0), or -1 (no ack) */
static inline int zd1_drc_ack(uint8_t code){
    switch(code){
    case ZD1_DRC_PAUSE: return 1;
    case ZD1_DRC_PLAY: return 0;
    case ZD1_DRC_RELEASE: return 4;
    case ZD1_DRC_ENABLE: return 5;
    default: return -1;
    }
}

